                ds.multiHomingRate = Math.min(80, ds.multiHomingRate + 8);
            }

            ds.providerChurnRate = Math.max(5, 35 - ds.trustIndex * 0.2 - ds.providerNps * 0.1 + (d.takeRate - 15) * 0.5);
            ds.clientChurnRate = Math.max(8, 60 - ds.platformLiquidity * 0.3 - ds.clientRetention * 0.2);

            if (setback || insolvent) ds.setbackPeriods += 1;

            ds.liquidityHistory.push(Math.round(ds.platformLiquidity));
            ds.gmvHistory.push(ds.gmv);
            ds.revenueHistory.push(ds.netRevenue);

            var sc = this._score(ds);
            var overallScore = sc.score;
            ds.scoreHistory.push(overallScore);
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, {
                overallScore: overallScore, score: overallScore, outcome: sc.outcome, performance: this._tier(overallScore).id
            });
            ds.performanceTier = this._tier(overallScore).id;

            this._notifyRound(spendCut, insolvent, fundingEvent, ds.fundingLiquidity);

            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
                self._describeCharts();
            })(state.currentPeriod + 1), 500);

            return {
                period: period,
                phase: phase,
                marketingBudget: dIn.marketingBudget,
                supplyVsDemandSplit: d.supplyVsDemandSplit,
                takeRate: d.takeRate,
                qualityInvestment: dIn.qualityInvestment,
                expansionInvestment: dIn.expansionInvestment,
                marketingSpent: d.marketingBudget,
                qualitySpent: d.qualityInvestment,
                expansionSpent: d.expansionInvestment,
                spendCut: spendCut ? 1 : 0,
                newProviders: newProviders,
                newClients: newClients,
                activeProviders: ds.activeProviders,
                activeClients: ds.activeClients,
                gmv: ds.gmv,
                netRevenue: ds.netRevenue,
                grossProfit: Math.round(grossProfit),
                cash: ds.cash,
                platformLiquidity: Math.round(ds.platformLiquidity),
                providerNps: ds.providerNps,
                clientRetention: ds.clientRetention,
                cacLtvRatio: ds.cacLtvRatio,
                multiHomingRate: ds.multiHomingRate,
                trustIndex: Math.round(ds.trustIndex),
                overallScore: overallScore,
                score: overallScore
            };
        }

        _t(key) {
            var v;
            try { v = window.mySimulation.t(key); } catch (e) { v = null; }
            if (typeof v !== 'string' || v === key) {
                try {
                    var lang = (window.vcI18n && window.vcI18n._lang) || 'en';
                    var tr = this._tr || (this._tr = this.getTranslations());
                    v = (tr[lang] && tr[lang][key]) || tr.en[key] || key;
                } catch (e2) { v = key; }
            }
            return v;
        }

        _f(key, a, b, c) {
            return String(this._t(key)).replace('{0}', a).replace('{1}', b).replace('{2}', c);
        }

        _notifyRound(spendCut, insolvent, fundingEvent, liq) {
            try {
                var ui = window.mySimulation && window.mySimulation.uiManager;
                if (!ui || typeof ui.showNotification !== 'function') return;
                if (insolvent) ui.showNotification(this._t('insolventNote'), 'warning');
                else if (spendCut) ui.showNotification(this._t('spendCutNote'), 'warning');
                if (fundingEvent === 'seriesA') ui.showNotification(this._f('fundingSeriesA', liq), 'success');
                if (fundingEvent === 'bridge') ui.showNotification(this._f('fundingBridge', liq), 'warning');
            } catch (e) {}
        }

        _describeCharts() {
            try {
                var st = window.mySimulation && window.mySimulation.state;
                var ds = (st && st.domainState) || {};
                var liq = (ds.liquidityHistory || []).join(', ');
                var rev = (ds.revenueHistory || []).join(', ');
