                if (a) { a.setAttribute('role', 'img'); a.setAttribute('aria-label', this._t('chartLiqAlt') + ' ' + (liq || '-')); }
                if (b) { b.setAttribute('role', 'img'); b.setAttribute('aria-label', this._t('chartFinAlt') + ' ' + (rev || '-')); }
            } catch (e) {}
        }

