        getPerformanceSummary(history) {
            if (!history || !history.length) return {};

            var lastState = history[history.length - 1];
            var ds = lastState.domainState || {};
            var self = this;
            var n = function(v) { return self._num(v); };

            var sc = this._score(ds);
            var mhs = sc.score;
            var tier = this._tier(mhs);
            var process = Math.max(0, Math.round(100 * (history.length - n(ds.setbackPeriods)) / history.length));

            var ratio = n(ds.activeProviders) > 0 ? n(ds.activeClients) / n(ds.activeProviders) : 0;
            var ratioTxt = (Math.round(ratio * 10) / 10).toFixed(1);
            if (((window.vcI18n && window.vcI18n._lang) || 'en') === 'es') ratioTxt = ratioTxt.replace('.', ',');
            var insights = [];
            if (ds.fundingRound === 'seriesA') insights.push(this._f('fundingSeriesA', n(ds.fundingLiquidity)));
            if (ds.fundingRound === 'bridge') insights.push(this._f('fundingBridge', n(ds.fundingLiquidity)));
            if (n(ds.takeExcessPeriods) > 0) insights.push(this._f('insTake', n(ds.takeExcessPeriods), n(ds.firstTakeExcess)));
            if (n(ds.earlyExpansionPeriods) > 0) insights.push(this._f('insExpand', n(ds.earlyExpansionPeriods), n(ds.firstEarlyExpansion)));
            if (n(ds.idleSupplyPeriods) > 0) insights.push(this._f('insIdle', n(ds.idleSupplyPeriods)));
            if (n(ds.cashShortPeriods) > 0) insights.push(this._f('insCash', n(ds.cashShortPeriods), n(ds.firstCashShort)));
            if (ratio >= 4 && ratio <= 6) insights.push(this._f('insRatioGood', ratioTxt));
            else if (ratio < 4) insights.push(this._f('insRatioLow', ratioTxt));
            else insights.push(this._f('insRatioHigh', ratioTxt));
            if (!n(ds.setbackPeriods)) insights.push(this._t('insClean'));

            // Turning point: the period with the largest fall in the score, else the funding milestone.
            var sh = Array.isArray(ds.scoreHistory) ? ds.scoreHistory : [];
            var worst = 0, worstAt = 0;
            for (var i = 1; i < sh.length; i++) {
                if (sh[i] - sh[i - 1] < worst) { worst = sh[i] - sh[i - 1]; worstAt = i + 1; }
            }
            var turningPoint;
            if (worstAt && worst <= -3) turningPoint = this._f('tpDrop', worstAt, sh[worstAt - 2], sh[worstAt - 1]);
            else if (ds.fundingRound) turningPoint = this._f('tpFunding', n(ds.fundingLiquidity));
            else turningPoint = this._f('tpSteady', mhs);

            return {
                mhs: mhs,
                score: mhs,
                overallScore: mhs,
                totalScore: mhs,
                composite: mhs,
                performance: tier.id,
                performanceKey: tier.id,
                performanceLabel: this._t(tier.key),
                outcomeScore: sc.outcome,
                processScore: process,
                turningPoint: turningPoint,
                questions: [this._t('dbQ1'), this._t('dbQ2'), this._t('dbQ3')],
                liquidity: Math.round(n(ds.platformLiquidity)),
                clientRetention: Math.round(n(ds.clientRetention)),
                cacLtvRatio: n(ds.cacLtvRatio),
                netRevenue: n(ds.netRevenue),
                providerNps: Math.round(n(ds.providerNps)),
                trustIndex: Math.round(n(ds.trustIndex)),
                cash: n(ds.cash),
                activeProviders: n(ds.activeProviders),
                activeClients: n(ds.activeClients),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var self = this;
            var t = function(k) { return self._t(k); };
            var money = function(v) { return '$' + Math.round(self._num(v)).toLocaleString(); };
            var li = function(arr) { return (arr || []).map(function(x) { return '<li>' + x + '</li>'; }).join(''); };
            var kpi = function(label, value) { return '<li><span>' + label + ':</span> <strong>' + value + '</strong></li>'; };
            var html = '<div class="nexus-debrief">'
                + '<p class="nexus-debrief-score"><span>' + t('mhsScore') + ':</span> <strong>' + self._num(summary.mhs) + '/100</strong> · '
                + '<span>' + t('tierLabel') + ':</span> <strong>' + (summary.performanceLabel || '') + '</strong></p>'
                + '<p class="nexus-debrief-sub"><span>' + t('dbOutcome') + ':</span> <strong>' + self._num(summary.outcomeScore) + '/100</strong> · '
                + '<span>' + t('dbProcess') + ':</span> <strong>' + self._num(summary.processScore) + '/100</strong></p>'
                + '<ul class="nexus-debrief-kpis">'
                + kpi(t('liquidityScore'), self._num(summary.liquidity) + '%')
                + kpi(t('clientRetention'), self._num(summary.clientRetention) + '%')
                + kpi(t('netRevenueMetric'), money(summary.netRevenue))
                + kpi(t('providerNps'), self._num(summary.providerNps))
                + kpi(t('providers'), self._num(summary.activeProviders))
                + kpi(t('clients'), self._num(summary.activeClients))
                + kpi(t('cashRunway'), money(summary.cash))
                + '</ul>'
                + '<h4>' + t('dbTurning') + '</h4><p>' + (summary.turningPoint || '') + '</p>'
                + '<h4>' + t('dbInsights') + '</h4><ul>' + li(summary.insights) + '</ul>'
                + '<h4>' + t('dbQuestions') + '</h4><ol>' + li(summary.questions) + '</ol>'
                + '</div>';
            this._showSummaryBox(html);
            return html;
        }

        _showSummaryBox(html) {
            try {
                var box = document.getElementById('summaryBox');
                var body = document.getElementById('summaryBody');
                if (box && body) { body.innerHTML = html; box.style.display = ''; }
            } catch (e) {}
        }

        _repaint() {
            try {
                var st = window.mySimulation && window.mySimulation.state;
                if (!st) return;
                this._updateBriefing(st);
                this._describeCharts();
                var box = document.getElementById('summaryBox');
                if (box && box.style.display !== 'none' && st.history && st.history.length) {
                    this.formatCompletionMessage(this.getPerformanceSummary(st.history));
                }
            } catch (e) {}
        }

        getHint(state, results) {
            if (!results) return null;
            var phase = Math.ceil(state.currentPeriod / 3);
            if (results.platformLiquidity < 30 && phase <= 2) {
                return window.mySimulation.t('recommendationLiquidity');
            }
            if (results.clientRetention < 25) {
                return window.mySimulation.t('recommendationRetention');
            }
            if (state.domainState.cash < 300000) {
                return window.mySimulation.t('hint_cash_low');
            }
            if (results.multiHomingRate > 50) {
                return window.mySimulation.t('hint_multihoming');
            }
            var phaseKey = this.PHASE_EVENTS[phase];
            if (phaseKey) {
                return window.mySimulation.t(phaseKey);
            }
            return null;
        }

